// Whole-street ("corridor") scenarios, following the four-scenario logic of
// thesis §8.2.6 (Existing / Minimal / Balanced / Maximum). The thesis does not
// publish its tree positions, so these layouts are generated by app rules:
//   Minimal  – one tree in each PGPI top-20 segment of this street, using the
//              primary species from the thesis decision record (Table D.1).
//   Balanced – one new tree in every segment whose measured GVI is still
//              below the ~20% scenario reference (alternating street sides).
//   Maximum  – fills footpath positions spaced one crown diameter apart on
//              both sides, minus the share already taken by existing canopy.
import { SPECIES_BY_ID, SPECIES_BY_NAME } from '../data/species.js';
import { SEGMENT_LENGTH, zonesFor } from '../data/streets.js';
import { canopyCover, gviProxy } from './metrics.js';
import { crownDiameter } from '../data/species.js';

export const SCENARIOS = [
  { id: 'existing', label: 'Existing', note: 'Measured today (thesis Table D.2)' },
  { id: 'minimal', label: 'Minimal', note: 'One tree in each top-20 priority segment' },
  { id: 'balanced', label: 'Balanced', note: 'One new tree in every segment still below ~20% GVI' },
  { id: 'maximum', label: 'Maximum', note: 'Trees one crown-width apart on both footpaths, where existing canopy leaves room' },
  { id: 'mine', label: 'My designs', note: 'Segments you drew in the designer' },
];

export const GVI_REFERENCE = 20;

function slots(street, sp, crownSize) {
  const fps = zonesFor(street).filter((z) => z.kind === 'footpath');
  const rows = fps.map((fp, side) => (side === 0 ? fp.u1 - 1.0 : fp.u0 + 1.0));
  const k = Math.max(1, Math.floor(SEGMENT_LENGTH / Math.max(6, crownDiameter(sp, crownSize))));
  const out = [];
  // alternate sides so partial fills stay balanced across the street
  for (let i = 0; i < k; i++) {
    rows.forEach((u, ri) => {
      const v = ((i + 0.5) * SEGMENT_LENGTH) / k;
      out.push({ u: Math.round(u * 10) / 10, v: Math.round((ri ? SEGMENT_LENGTH - v : v) * 10) / 10 });
    });
  }
  return out;
}

export function speciesFor(seg, fallbackId) {
  const name = seg.decision?.species;
  return (name && SPECIES_BY_NAME[name]) || SPECIES_BY_ID[fallbackId];
}

let n = 0;
const tid = (seg) => `${seg.id}-c${++n}`;

export function segmentLayout(street, seg, mode, { fallbackId, crownSize, myDesigns }) {
  if (mode === 'existing') return [];
  if (mode === 'mine') return myDesigns[seg.id] || [];
  const sp = speciesFor(seg, fallbackId);
  const all = slots(street, sp, crownSize);
  if (mode === 'minimal') {
    if (!seg.shortlist) return [];
    const centre = all.slice().sort((p, q) => Math.abs(p.v - 10) - Math.abs(q.v - 10))[0];
    return [{ id: tid(seg), speciesId: sp.id, ...centre }];
  }
  if (mode === 'maximum') {
    const room = Math.round(all.length * (1 - seg.canopy / 100));
    return all.slice(0, room).map((p) => ({ id: tid(seg), speciesId: sp.id, ...p }));
  }
  // balanced: one tree, alternating sides from segment to segment
  if (seg.gvi >= GVI_REFERENCE) return [];
  const side = seg.index % 2;
  const p = all.filter((q, i) => i % 2 === side).sort((a, b) => Math.abs(a.v - 10) - Math.abs(b.v - 10))[0] || all[0];
  return [{ id: tid(seg), speciesId: sp.id, ...p }];
}

export function corridorScenario(street, mode, opts) {
  const layouts = street.segments.map((seg) => segmentLayout(street, seg, mode, opts));
  const rows = street.segments.map((seg, i) => {
    const trees = layouts[i];
    const addedCanopy = trees.length ? canopyCover(street, trees, SPECIES_BY_ID, opts.crownSize, 0.4).pct : 0;
    // Along-street views also see new trees in the two segments either side.
    const seen = [];
    for (let j = Math.max(0, i - 2); j <= Math.min(layouts.length - 1, i + 2); j++) {
      layouts[j].forEach((t) => seen.push({ ...t, v: t.v + (j - i) * SEGMENT_LENGTH }));
    }
    const addedGvi = seen.length ? gviProxy(street, seen, SPECIES_BY_ID, opts.crownSize, 0, 32).pct : 0;
    return {
      seg,
      trees,
      canopy: Math.min(100, seg.canopy + addedCanopy),
      gvi: Math.min(100, seg.gvi + addedGvi),
      addedCanopy,
      addedGvi,
    };
  });
  const mean = (k) => rows.reduce((a, r) => a + r[k], 0) / rows.length;
  return {
    rows,
    trees: rows.reduce((a, r) => a + r.trees.length, 0),
    canopy: mean('canopy'),
    gvi: mean('gvi'),
    existingCanopy: street.segments.reduce((a, s) => a + s.canopy, 0) / street.segments.length,
    existingGvi: street.segments.reduce((a, s) => a + s.gvi, 0) / street.segments.length,
    reaching: rows.filter((r) => r.gvi >= GVI_REFERENCE).length,
  };
}

// Thesis Table 8.4 (corridor scenarios, Hindley and Gouger only)
export const THESIS_T84 = {
  hindley: { existing: [0, 0.3, 0.0], minimal: [12, 11.0, 20.4], balanced: [24, 25.0, 27.4], maximum: [46, 43.0, 45.6] },
  gouger: { existing: [0, 14.3, 8.2], minimal: [7, 18.0, 13.5], balanced: [18, 24.0, 20.0], maximum: [32, 34.0, 28.5] },
};
